import 'dart:io';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import 'package:cross_file/cross_file.dart';import 'package:share_plus/share_plus.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';import 'record_editor_screen.dart';
class RecordsScreen extends ConsumerWidget{const RecordsScreen({super.key});Future<void> openAttachment(BuildContext context,PetRecord record)async{final path=record.attachmentPath;if(path.isEmpty)return;final file=File(path);if(!await file.exists()){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('This attachment is no longer available on this device.')));return;}final lower=path.toLowerCase();if(lower.endsWith('.jpg')||lower.endsWith('.jpeg')||lower.endsWith('.png')){if(context.mounted)showDialog(context:context,builder:(_)=>Dialog(child:InteractiveViewer(child:Image.file(file,fit:BoxFit.contain))));}else{await SharePlus.instance.share(ShareParams(files:[XFile(path)],subject:record.title));}}
@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider),pet=c.selectedPet;final records=pet==null?<PetRecord>[]:c.items('pet_records').map(PetRecord.fromMap).where((e)=>e.petId==pet.id).toList()..sort((a,b)=>b.eventDate.compareTo(a.eventDate));return Scaffold(appBar:AppBar(title:const Text('Health record organizer'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const RecordEditorScreen())),icon:const Icon(Icons.add))]),body:records.isEmpty?const Center(child:Text('No records saved for this pet.')):ListView(padding:const EdgeInsets.all(16),children:records.map((e)=>Card(child:ListTile(leading:const Icon(Icons.folder_copy_outlined,color:Color(0xFF39845A)),title:Text(e.title),subtitle:Text('${e.type} · ${DateFormat.yMMMd().format(e.eventDate)} · Entered by you\n${e.clinic}${e.attachmentPath.isEmpty?'':'\nAttachment saved on device'}'),onTap:e.attachmentPath.isEmpty?null:()=>openAttachment(context,e),trailing:e.attachmentPath.isEmpty?null:IconButton(tooltip:'Share attachment',icon:const Icon(Icons.ios_share),onPressed:()=>openAttachment(context,e))))).toList()));}}
